-- ============================================================
-- Hoxiee — Question bank seed data
-- Auto-generated from questions.json (1000 questions)
-- Run this in: Supabase Dashboard → SQL Editor → New query
-- Safe to re-run: uses ON CONFLICT to upsert existing rows.
-- ============================================================

create table if not exists public.quiz_questions (
  id integer primary key,
  subject text not null,
  category text not null,
  prompt text not null,
  answer text not null,
  unique (subject, category, id)
);

alter table public.quiz_questions enable row level security;

-- ============================================================
-- Math · Algebra (334 questions)
-- ============================================================
on conflict (id) do update set
  subject = excluded.subject,
  category = excluded.category,
  prompt = excluded.prompt,
  answer = excluded.answer;

-- ============================================================
-- English · Grammar (334 questions)
-- ============================================================
on conflict (id) do update set
  subject = excluded.subject,
  category = excluded.category,
  prompt = excluded.prompt,
  answer = excluded.answer;

-- ============================================================
-- English · Spelling (332 questions)
